export declare function tenantRoom(tenantId: string): string;
/** 项目房间名（看板页按项目加入；必须带租户前缀，防跨租户 projectId 碰撞/窃听） */
export declare function projectRoom(tenantId: string, projectId: string): string;
/** 广播帧形状（前端 boardStore/通知轮询降级点订阅契约；与 domain-events payload 信封一致） */
